from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def min_cost_paint(costs: list[list[int]]) -> int:
    a, b, c = costs[0]
    for red, blue, green in costs[1:]:
        a, b, c = red + min(b, c), blue + min(a, c), green + min(a, b)
    return min(a, b, c)

